edits.newCode:
mineSigns = []; raidHeat = 0; raidT = 0; mineNext = 0;
/* the books are re-seeded from the manual for THIS army in THIS era, and
   the episode is closed: a restarted match must not credit its first wave
   to the previous one's choices */
wavePlan = null; waveSerial = 0; armNow = null;
lastEra = null; lastPlate = 0; bookInit();

/* ================= the loop that says a choice WORKED ====================
   Six records in this file remember pain and not one remembers payment,
   which is why the same plot produces the same wave for twenty-five minutes:
   with no value attached to a choice there is nothing a second choice can
   beat. This is the missing half, and it is deliberately three SMALL books
   rather than one clever one.

     emph   what the wave is made of  balanced | armour | gunline | swarm
     axis   which way it goes in      direct   | flank  | rear
     tempo  when it is let go         standard | rush   | mass

   Ten arms in three independent books, not one bandit over the 36
   combinations. A match is 10 to 25 waves: 36 arms would be sampled half a
   time each and the commander would end the battle knowing nothing while
   looking random, which is "variety is not intelligence" written as
   arithmetic. Ten arms in three books get three to eight pulls apiece, which
   is enough for one mean to separate from its neighbour. The price is that
   INTERACTIONS are invisible - a gun line coming in from the rear may be bad
   while each half looks sound - and it is paid knowingly: all three books
   are scored against the same reward, so a consistently bad pairing still
   drags both its arms down, only more slowly.

   ALL THREE ARMS ARE CHOSEN AT ONE MOMENT: when the previous wave settles.
   That is not tidiness, it is what makes attribution exact. The emphasis arm
   chosen at the settling of wave k-1 is the one in force while wave k is
   BUILT; the tempo arm is the one that sets wave k's release gate; the axis
   arm is the one pickApproach leans on when wave k marches. One wave is one
   episode and one pull of each book.

   WHY THE AIR FORCE IS NOT AN ARM. An arm has to be buildable, has to change
   what the wave does, and has to be CREDITABLE. Aircraft fail the third:
   they are not in attackWave, reapWave never sees one die, and a sortie is
   flown against warAim() on its own clock. An air arm would put noise into
   all three books in exchange for a column nothing could score. It becomes
   legitimate the day a sortie carries a wave id. The navy is the same case.

   DIFFICULTY runs through one gate and one multiplier, exactly as the rest
   of the file does it: learnOn() is read >= 0.35, so a Recruit never opens an
   episode, never chooses, never writes a book and never touches storage - it
   gets balanced/direct/standard, which is bit-for-bit what it does today -
   and every lever below is scaled by grip = D.read, so a Regular plays the
   manual with a tremor and a Warlord genuinely re-plans.                  */
const ARMS = {
  /* index 0 is the fallback when everything ties, so index 0 is TODAY'S
     BEHAVIOUR in each book. That is what makes a missing prior safe. */
  emph:  ["balanced", "armour", "gunline", "swarm"],
  axis:  ["direct", "flank", "rear"],
  tempo: ["standard", "rush", "mass"],
};
const EMPH = {
  /* A lean on the shopping list, never a replacement for it. counterMix has
     already answered "what does the picture demand"; this answers "and which
     of those answers has been paying". The largest multiplier is 1.45 and
     grip shrinks it further - at Regular a 1.45 arrives as 1.16. */
  balanced: null,                                   // today's list, untouched
  armour:  { veh: { mbt: 1.35, heavy: 1.35, tankdestroyer: 1.25, lighttank: 1.10 },
             inf: { at: 1.10 } },
  gunline: { veh: { spg: 1.45, mlrs: 1.40, radarv: 1.15 },
             inf: { mortar: 1.30, sniper: 1.20 } },
  swarm:   { inf: { rifle: 1.30, at: 1.25, mg: 1.25, mortar: 1.10 },
             veh: { ifv: 1.15 } },
};
const TEMPO = { standard: 1.00, rush: 0.75, mass: 1.40 };
const PRIOR_N = 3;             // the manual is worth three imaginary waves
const DRIFT = 0.45;            // how far a learned value may sit from it
const EXPLORE = 0.22;          // UCB constant, before grip
const AXIS_PUSH = 14;          // score points against a lane of the wrong class
const WAVE_FLOOR = 1200;       // a five-man probe cannot score +8 on one kill
const REWARD_CAP = 1.2, KILL_R = 14;
const LEARN_KEY = "ironfront.learn.v1";
const LEARN_PERSIST = true;    // one flag; false removes cross-match memory entirely

function learnOn() { return !!book && (D.read || 0) >= 0.35; }

/* ---- where the doctrine prior comes in, and what happens if it never does -
   ONE narrow contract, read through try/catch at init and never again:
     Doctrine.emphasis(faction, era, picture) -> { balanced, armour, gunline,
     swarm } as shares summing to about one.
   If the sibling ships a per-ROLE weight map instead (Doctrine.mix), the
   arm's own roles are summed out of it, so either shape works. A share is
   turned into a starting value by subtracting the flat share, so a manual
   with no opinion starts every arm at zero - which is exactly the state when
   there is no manual at all. If Doctrine is absent every arm ties, UCB takes
   index 0 of each list, and that is balanced/direct/standard: precisely what
   this commander does today. A prior landing later changes the opening and
   nothing else. */
function priorFor(dim) {
  const out = {};
  for (const arm of ARMS[dim]) out[arm] = 0;
  if (dim !== "emph") return out;          // only the mixture has a manual
  try {
    const Dc = (typeof Doctrine !== "undefined") ? Doctrine : null;
    if (!Dc) return out;
    let sh = null;
    if (Dc.emphasis) sh = Dc.emphasis(P.faction, P.era, foeArms());
    else if (Dc.mix) {
      const w = Dc.mix(P.faction, P.era, foeArms()) || {};
      sh = {};
      for (const arm of ARMS.emph) {
        const E = EMPH[arm];
        let s = 0;
        if (!E) s = 0.25;                  // balanced is the flat share by definition
        else for (const cat of ["inf", "veh"])
          for (const role in (E[cat] || {})) s += ((w[cat] && w[cat][role]) || 0);
        sh[arm] = s;
      }
    }
    if (!sh) return out;
    let tot = 0, n = 0;
    for (const arm of ARMS.emph) { tot += Math.max(0, sh[arm] || 0); n++; }
    if (!(tot > 0)) return out;
    /* PSEUDO-COUNTS. Each arm starts with PRIOR_N imaginary observations at
       this value, so after PRIOR_N real waves the evidence weighs as much as
       the manual. THREE, and the number is chosen from the horizon: a match
       is 10 to 25 waves shared between four emphasis arms, so an arm gets
       three to six pulls. At six the manual would still be half the estimate
       at the final whistle and every match would open and close the same
       way, which is the complaint this change exists to answer. At one, a
       single unlucky wave moves an arm by half the reward - three bad fights
       and the commander has concluded that anti-tank missiles do not work.
       At three, one r = -1.0 wave against a prior of +0.20 leaves q = -0.10:
       moved unmistakably, and recoverable in two good waves. */
    for (const arm of ARMS.emph)
      out[arm] = U.clamp((Math.max(0, sh[arm] || 0) / tot - 1 / n) * 1.6, -0.4, 0.4);
  } catch (e) { /* a manual that throws is a manual we do not have */ }
  return out;
}

function bookInit() {
  book = {};
  for (const dim in ARMS) {
    const pr = priorFor(dim);
    book[dim] = {};
    for (const arm of ARMS[dim]) {
      const p = U.clamp(pr[arm] || 0, -0.4, 0.4);
      book[dim][arm] = { n: PRIOR_N, q: p, p: p };
    }
  }
  loadBook();
  chooseArms();
}

/* An arm this army cannot field must never be sampled. Measured off unitFor
   across all six eras: KPA has no `heavy` before e00, ROC no MLRS in e50,
   PACT no tank destroyer in e50. Spending a whole wave to discover that the
   factory cannot build a howitzer is not exploration, it is a wasted wave -
   and it would write a real negative into an arm that was never tried. */
function armReady(dim, arm) {
  if (dim === "emph") {
    if (arm === "gunline") return P.tech >= 2 && !!unitFor(P.faction, "spg", P.era);
    if (arm === "armour")  return P.tech >= 2 && !!unitFor(P.faction, "mbt", P.era);
    return true;
  }
  /* a commander that does not manoeuvre has no lane to choose: launchGroundWave
     hands out a flat attackmove below micro 0.35 and pickApproach never runs */
  if (dim === "axis") return (D.micro === undefined ? 0.4 : D.micro) >= 0.35;
  return true;
}

/* ---- the policy: UCB1 over pseudo-counts ----
   Epsilon-greedy spends a fixed fraction of waves on a uniformly random
   choice for ever, and a wave is 4,721 credits for a 1950s KPA and 15,039
   for a 2020s ROC (measured at the counterMix floor) - far too expensive a
   coin to keep flipping, and it never finishes exploring. Softmax needs a
   temperature schedule invented by hand, which is the hand-tuned-constant
   problem again. UCB needs neither: with n seeded at three the opening bonus
   is 0.22*sqrt(ln 13/3) = 0.21 at full grip, the same order as a real
   difference in q, so an untried arm gets looked at; by ten pulls it is 0.11
   and still falling. EXPLORATION DECAYS BECAUSE THE COUNTS GROW - there is
   no schedule to tune and no dice to explain away, and two commanders differ
   because their PICTURES differ. */
function pickArm(dim) {
  const b = book[dim], grip = D.read === undefined ? 1 : D.read;
  let T = 0;
  for (const k in b) T += b[k].n;
  const C = EXPLORE * grip;
  let best = null, bs = -Infinity;
  for (const arm of ARMS[dim]) {
    if (!armReady(dim, arm)) continue;
    const a = b[arm];
    const s = a.q + C * Math.sqrt(Math.log(1 + T) / a.n);
    if (s > bs) { bs = s; best = arm; }
  }
  return best || ARMS[dim][0];
}
function chooseArms() {
  if (!learnOn()) { armNow = null; return; }
  armNow = { emph: pickArm("emph"), axis: pickArm("axis"), tempo: pickArm("tempo") };
}
function armFor(dim) {
  if (!armNow) chooseArms();
  return armNow ? armNow[dim] : ARMS[dim][0];
}

/* counterMix answers the picture. This leans the answer toward whatever has
   been paying, and it is a separate function on purpose: counterMix stays
   the pure observation-to-weights map, and intel().mix keeps returning it
   unchanged, so what behaviour test [29] measures is not touched by any of
   this. The bound is the last line of the loop - a multiplier is only ever
   applied to a role counterMix ALREADY PUT ON THE LIST. The learner
   reweights doctrine; it cannot invent a role the picture never asked for,
   and it cannot zero one either. */
function doctrineMix(a) {
  const mix = counterMix(a);
  const grip = D.read === undefined ? 1 : D.read;
  if (grip <= 0 || !learnOn()) return mix;
  const E = EMPH[armFor("emph")];
  if (!E) return mix;
  for (const cat of ["inf", "veh"]) {
    const m = E[cat];
    if (!m) continue;
    for (const role in m) {
      if (mix[cat][role] === undefined) continue;   // not on the list: not our business
      mix[cat][role] *= 1 + (m[role] - 1) * grip;
    }
  }
  return mix;
}

/* Bearings are measured AT THE OBJECTIVE, from the direction home lies in,
   because that is the frame pickApproach already builds its rose in: a gate
   at zero is between us and the target - the single carved road A* wants
   anyway - and one at pi is behind it. 50 and 130 degrees. */
function axisClass(a, t) {
  const home = Math.atan2(P.homeY - t.y, P.homeX - t.x);
  const d = Math.abs(U.angDiff(a, home));
  return d < 0.87 ? "direct" : d < 2.27 ? "flank" : "rear";
}
/* A LEAN, NEVER AN OVERRIDE, and the calibration is the whole of it.
   pickApproach scores a lane in the tens: one dead MBT is graveWeight 4.75 *
   9 = 43 points, the staleness term tops out near 39, a 60-tile drive is 33.
   Fourteen points is a third of a dead tank - enough to decide between lanes
   that are otherwise close, and never enough to talk the wave onto a lane
   that is mined or under fire. */
function axisBias(a, t) {
  if (!armNow || !learnOn()) return 0;
  const grip = D.read === undefined ? 1 : D.read;
  return axisClass(a, t) === armNow.axis ? 0 : AXIS_PUSH * grip;
}

/* ---- the episode ----
   Opened when a wave is committed, closed when it takes the objective, is
   destroyed, or runs out of clock. There is never more than one open: the
   launch force-settles the last, and launchGroundWave replaces attackWave
   wholesale anyway, so nothing is left to overlap. */
function openWave(t) {
  settleWave();
  if (!learnOn() || !t) return;
  const p = { w: ++waveSerial, t0: G.time, cost: 0, hp0: 0, n: 0,
              emph: armFor("emph"), tempo: armFor("tempo"),
              /* NOT armFor("axis"). A choice that was not acted on must not
                 be credited: a siege, or a flat attackmove below micro 0.35,
                 never marches a chosen lane. Only the one site that actually
                 does - lastAxes.unshift in launchGroundWave - fills this in,
                 and learn() no-ops on null. */
              axis: null,
              aimId: t.id, worth: t.worth || 0, kills: 0, took: 0,
              cx: P.homeX, cy: P.homeY };
  for (const u of attackWave) {
    if (!u || u.dead) continue;
    u._wave = p.w;
    p.cost += (u.def && u.def.cost) || 300;
    p.hp0 += u.hp; p.n++;
  }
  wavePlan = p;
}

/* Run every think, straight after reapWave: the casualty list is fresh and
   attackWave has just been pruned. */
function learnTick() {
  if (!book) return;
  bookWatch();
  const p = wavePlan;
  if (!p) return;
  const now = G.time;
  let cx = 0, cy = 0, n = 0, hp = 0;
  for (const u of attackWave) if (!u.dead) { cx += u.x; cy += u.y; n++; hp += u.hp; }
  if (n) { cx /= n; cy /= n; p.cx = cx; p.cy = cy; }
  /* ---- what we WATCHED die ----
     Three gates, all of them fog. The record is one our own sensors wrote;
     the track has to be under eight seconds old, which is the same window
     liveTrack() demands before it will let a weapon aim at one; and it has
     to have fallen within fourteen tiles of our own wave, so it is something
     this wave was standing next to and not a hauler a base gun caught at the
     other end of the map. `cost` was read off the recognition manual at the
     moment of contact. No enemy object list is touched here. */
  if (n) for (const r of seenU.values()) {
    if (r.killed || !r.ref || !r.ref.dead) continue;
    if (now - r.t > 8) continue;
    r.killed = 1;
    if (U.dist(r.x, r.y, cx, cy) < CFG.TILE * KILL_R) p.kills += r.cost || 300;
  }
  /* the objective came down: the wave did what it was sent to do */
  if (!p.took) {
    const rec = seenB.get(p.aimId);
    if (rec && (rec.gone || (rec.ref && rec.ref.dead))) p.took = 1;
  }
  if (p.took) { settleWave(); return; }
  if (!attackWave.length || hp <= p.hp0 * 0.25) { settleWave(); return; }
  if (now - p.t0 > (D.waveTime || 150) * 1.6) settleWave();
}

/* ---- the reward, in credits, as a ratio ----
   A wave is 4,721 credits for a 1950s KPA and 15,039 for a 2020s ROC
   (measured off unitFor at the counterMix floor), so an absolute figure
   would have one book learning two different games. Dividing by what this
   wave actually cost makes every era and every army comparable and puts r in
   about [-1.2, 1.2], which is the scale DRIFT 0.45 and EXPLORE 0.22 are
   sized against. */
function settleWave() {
  const p = wavePlan;
  wavePlan = null;
  if (!p || !learnOn()) return;
  let lost = 0;
  for (const g of graves) if (g.w === p.w) lost += g.cost;
  /* 0.8 on the prize: worthOf() already prices what REMOVING it costs them,
     and the previous wave may have cut it half down before we arrived. */
  const gain = p.kills + (p.took ? p.worth * 0.8 : 0);
  /* NO EVIDENCE, NO UPDATE. A wave recalled to defend the base, or one whose
     objective an ally finished, produces a flat 0.0 - and a 0.0 written into
     an arm is a claim that the arm is MEDIOCRE, which the book then acts on
     for the rest of the match. Silence is the honest answer. */
  if (p.n < 4 || (lost < p.cost * 0.08 && gain === 0)) { chooseArms(); return; }
  const r = U.clamp((gain - lost) / Math.max(WAVE_FLOOR, p.cost),
                    -REWARD_CAP, REWARD_CAP);
  learn("emph", p.emph, r);
  learn("axis", p.axis, r);
  learn("tempo", p.tempo, r);
  chooseArms();
  saveBook();
}
function learn(dim, arm, r) {
  const a = arm && book[dim] && book[dim][arm];
  if (!a) return;                                  // a choice never acted on
  a.n++;
  /* The step never falls below 1/(PRIOR_N + 8) = 1/11. An estimate that
     could not move after twenty observations is exactly the stale book that
     the enemy re-equipping a generation makes worthless: eight fresh waves
     have to be able to re-shape it. */
  a.q += (r - a.q) / Math.min(a.n, PRIOR_N + 8);
  /* THE BOUND, and it is the owner's "reasonable way" made arithmetic: a
     commander may lean on experience and may never abandon the manual. It
     scales with read for the same reason every other lever in this file
     does - a Regular may move 0.16 off doctrine, a Warlord 0.45. */
  const dr = DRIFT * (D.read === undefined ? 1 : D.read);
  a.q = U.clamp(a.q, a.p - dr, a.p + dr);
}

/* ---- when the estimate is about to be about the wrong war ----
   An era step re-equips both armies: our own NATO mbt goes from 855 credits
   at e60 to 1,500 at e20 and its gun with it, and the plate it is shooting
   at moves as far. So on an era change, and when the heaviest plate we have
   SEEN jumps by a quarter, every value is pulled a third of the way home to
   doctrine and its count rewound with it. Not a reset: half of what was
   learned is about this player rather than about this equipment. */
function bookShock(f) {
  for (const dim in book) for (const arm in book[dim]) {
    const a = book[dim][arm];
    a.q += (a.p - a.q) * f;
    a.n = PRIOR_N + (a.n - PRIOR_N) * (1 - f);
  }
}
function bookWatch() {
  if (lastEra === null) lastEra = P.era;
  if (P.era !== lastEra) { lastEra = P.era; bookShock(0.34); }
  const pl = foeArms().plate || 0;          // memoised; this costs an integer compare
  if (lastPlate > 0 && pl > lastPlate * 1.25) bookShock(0.34);
  if (pl > lastPlate) lastPlate = pl;
}

/* ---- across matches: worth it, narrowly, and only like this ----
   Ten to twenty-five waves is genuinely short for four arms, and carrying
   the emphasis estimate is what makes the commander feel as though it has
   learned the PLAYER. Carried over whole it would make the AI more
   predictable every match, which is the complaint this change exists to
   answer. So: the emphasis book only - a lane and a release gate are
   properties of this map and this base, not of this opponent - keyed on our
   own faction and era, loaded at HALF the drift it earned with its count
   capped at four, version stamped, every number sanitised, at most eight
   slots, and off entirely below read 0.60. A new match opens with an opinion
   and still explores. LEARN_PERSIST = false removes the whole thing. */
function learnSlot() { return P.faction + "@" + (P.era || CUR_ERA); }
function num(v, d) { return (typeof v === "number" && isFinite(v)) ? v : d; }
function loadBook() {
  if (!LEARN_PERSIST || (D.read || 0) < 0.60) return;
  try {
    const raw = localStorage.getItem(LEARN_KEY);
    if (!raw) return;
    const o = JSON.parse(raw);
    if (!o || o.v !== 1 || !o.e) return;
    const s = o.e[learnSlot()];
    if (!s) return;
    for (const arm of ARMS.emph) {
      const rec = s[arm], a = book.emph[arm];
      if (!rec || !a || rec.length !== 2) continue;
      a.q = U.clamp(a.p + (num(rec[1], a.p) - a.p) * 0.5, a.p - DRIFT, a.p + DRIFT);
      a.n = U.clamp(num(rec[0], PRIOR_N), PRIOR_N, PRIOR_N + 4);
    }
  } catch (e) { /* no storage, a private window, or somebody else's JSON */ }
}
function saveBook() {
  if (!LEARN_PERSIST || (D.read || 0) < 0.60) return;
  try {
    let o = null;
    try { o = JSON.parse(localStorage.getItem(LEARN_KEY) || "null"); } catch (e2) { o = null; }
    if (!o || o.v !== 1 || !o.e) o = { v: 1, e: {} };
    const s = {};
    for (const arm of ARMS.emph) {
      const a = book.emph[arm];
      s[arm] = [Math.round(a.n), Math.round(a.q * 1000) / 1000];
    }
    o.e[learnSlot()] = s;
    const keys = Object.keys(o.e);              // eight slots: a hint, not a save game
    while (keys.length > 8) delete o.e[keys.shift()];
    localStorage.setItem(LEARN_KEY, JSON.stringify(o));
  } catch (e) { }
}

/* exposed for the same reason `look`, `graves` and `axes` already are: so a
   test or an overlay can see whether any of this is firing, rather than
   inferring it from a commander that quietly never changes its mind */
function bookDump() {
  if (!book) return null;
  const o = { arms: armNow, waves: waveSerial,
              open: wavePlan ? { w: wavePlan.w, emph: wavePlan.emph,
                                 axis: wavePlan.axis, tempo: wavePlan.tempo,
                                 cost: wavePlan.cost, kills: wavePlan.kills,
                                 took: wavePlan.took } : null };
  for (const dim in book) {
    o[dim] = {};
    for (const arm in book[dim]) {
      const a = book[dim][arm];
      o[dim][arm] = { n: Math.round(a.n * 100) / 100,
                      q: Math.round(a.q * 1000) / 1000,
                      p: Math.round(a.p * 1000) / 1000 };
    }
  }
  return o;
}

/* ---- build toward a mixture instead of rolling for one ----

reapWave();
/* ...and now the other half of the same sweep: what the wave achieved for
   those graves. reapWave writes the cost of our dead; learnTick prices the
   exchange and closes the episode when it has resolved. */
learnTick();
navalWave = navalWave.filter(u => !u.dead);

bookWave();
/* bookWave records the hit points this wave was committed with; openWave
   records the CHOICES it was committed on, and tags every unit so its
   grave can be credited to this wave and no other. */
openWave(t);

/* the wave is committed to this bearing here and nowhere else, so this is
   where the axis book is told what was tried. A siege or a flat attackmove
   returned above and leaves the plan's axis null, and learn() ignores it:
   a choice that was not acted on must never be scored. */
if (wavePlan) wavePlan.axis = axisClass(ap.a, t);
lastAxes.unshift(ap.a);

/* TEMPO, the third book. Veteran waveTime 150 and waveSize 10 become 112s
   and 7 on `rush`, 210s and 13.5 on `mass` at full grip - and a Veteran
   NATO wave of 16 costs 12,930 credits against 8,900 for one of 11 (both
   measured off unitFor at the counterMix floor), so this is a real
   decision about how much is put on the table at once and not a cosmetic
   timer. At read 0 the arm is `standard`, tp is 1.0, and this is the line
   that was here before. */
const tp = 1 + (TEMPO[armFor("tempo")] - 1) * (D.read === undefined ? 1 : D.read);
if (waveT <= 0 && army.length >= wantSize * 0.8 * tp) {

arms: foeArms(), mix: counterMix(foeArms()),
/* `mix` is the picture's answer and is what test [29] measures;
   `doctrine` is that answer after the learned lean, which is
   what the factories are actually told to build. */
doctrine: doctrineMix(foeArms()), learn: bookDump(),

/* Anything the game remembers about the player between matches has to be
   something the player can delete. This is the whole of that memory: one
   key, four numbers per faction-and-era slot. */
forgetLearned() { try { localStorage.removeItem("ironfront.learn.v1"); } catch (e) {} },
learnOf(player) {
  for (const c of commanders) if (c.player === player) return c.intel().learn;
  return null;
},
personalities: PERSONALITY_LIST,
